-- VYAPAAR sample data. GENERATED FILE -- do not edit by hand.
--
-- Realistic demo data for a wholesale garlic business, covering 2026-04-01 to 2026-10-21
-- so that every report has something to show.
--
-- WARNING: this DELETES everything in the six business tables first. Never run it on a
-- database holding real books. It is safe on a demo or a fresh database.
--
-- Load it with:
--   mysql --host=HOST --port=PORT --user=avnadmin --password --ssl-mode=REQUIRED \
--         vyapaar < database/sample_data.sql

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM payments;
DELETE FROM sales;
DELETE FROM purchases;
DELETE FROM products;
DELETE FROM customers;
DELETE FROM suppliers;
ALTER TABLE payments  AUTO_INCREMENT = 1;
ALTER TABLE sales     AUTO_INCREMENT = 1;
ALTER TABLE purchases AUTO_INCREMENT = 1;
ALTER TABLE products  AUTO_INCREMENT = 1;
ALTER TABLE customers AUTO_INCREMENT = 1;
ALTER TABLE suppliers AUTO_INCREMENT = 1;
SET FOREIGN_KEY_CHECKS = 1;

